mapper.select:
SELECT ad.id, add.id as detailId, ad.platform_code AS platformCode, ad.so_id AS soId, ad.so_code AS soCode, ad.shop_id AS shopId, ad.shop_name AS shopName, ad.track_no AS trackNo, ad.trade_create_time AS tradeCreateTime, ad.out_bound_time AS outBoundTime, ad.warehouse_name AS warehouseName, ad.is_outstock AS isSystemOut, add.platform_sku as platformSku, add.sku_no as skuNo, add.order_line_qty as qty FROM aliexpress_delivery ad INNER join aliexpress_delivery_detail add on ad.id = add.main_id and add.is_deleted = false WHERE ${params.sqlMap.default} and ad.is_deleted = FALSE ORDER BY
${item.field} ${item.sort}
ad.create_time DESC
